using Contoso.Scoring;

namespace Contoso.Scoring.Tests;

[TestClass]
public sealed class ScoreCalculatorTests
{
    private readonly ScoreCalculator _calculator = new();

    // --- CalculatePercentage: boundary & range checks ---

    [TestMethod]
    [DataRow(10, 10, 100.0, DisplayName = "Perfect score")]
    [DataRow(0, 10, 0.0, DisplayName = "Zero correct")]
    [DataRow(1, 2, 50.0, DisplayName = "Half correct")]
    [DataRow(3, 4, 75.0, DisplayName = "Three quarters")]
    public void CalculatePercentage_ValidInputs_ReturnsExpected(int correct, int total, double expected)
    {
        var result = _calculator.CalculatePercentage(correct, total);
        Assert.AreEqual(expected, result);
    }

    [TestMethod]
    public void CalculatePercentage_Result_IsInValidRange()
    {
        var result = _calculator.CalculatePercentage(7, 10);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);  // result > 0
        Assert.IsLessThan(100.0, result);   // result < 100
    }

    [TestMethod]
    public void CalculatePercentage_PerfectScore_IsNotGreaterThan100()
    {
        var result = _calculator.CalculatePercentage(10, 10);

        Assert.AreEqual(100.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void CalculatePercentage_ZeroTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(0, 0));
    }

    [TestMethod]
    public void CalculatePercentage_NegativeCorrect_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(-1, 10));
    }

    [TestMethod]
    public void CalculatePercentage_CorrectExceedsTotal_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.CalculatePercentage(11, 10));
    }

    // --- GetGrade: boundary tests at each threshold ---

    [TestMethod]
    [DataRow(90.0, "A", DisplayName = "Exact A boundary")]
    [DataRow(80.0, "B", DisplayName = "Exact B boundary")]
    [DataRow(70.0, "C", DisplayName = "Exact C boundary")]
    [DataRow(60.0, "D", DisplayName = "Exact D boundary")]
    [DataRow(59.9, "F", DisplayName = "Just below D")]
    public void GetGrade_AtBoundary_ReturnsExpectedGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(percentage));
    }

    [TestMethod]
    [DataRow(100.0, "A")]
    [DataRow(95.0, "A")]
    [DataRow(89.9, "B")]
    [DataRow(85.0, "B")]
    [DataRow(79.9, "C")]
    [DataRow(69.9, "D")]
    [DataRow(0.0, "F")]
    public void GetGrade_WithinRange_ReturnsExpectedGrade(double percentage, string expected)
    {
        Assert.AreEqual(expected, _calculator.GetGrade(percentage));
    }

    // --- NormalizeScore: range & capping ---

    [TestMethod]
    public void NormalizeScore_MidRange_ReturnsValueInRange()
    {
        var result = _calculator.NormalizeScore(45, 100);

        Assert.IsInRange(result, 0.0, 100.0);
        Assert.IsGreaterThan(0.0, result);
        Assert.IsLessThan(100.0, result);
        Assert.AreEqual(45.0, result);
    }

    [TestMethod]
    public void NormalizeScore_ExceedsMax_CapsAt100()
    {
        var result = _calculator.NormalizeScore(150, 100);

        Assert.AreEqual(100.0, result);
        Assert.IsInRange(result, 0.0, 100.0);
    }

    [TestMethod]
    public void NormalizeScore_ZeroRaw_ReturnsZero()
    {
        var result = _calculator.NormalizeScore(0, 100);
        Assert.AreEqual(0.0, result);
    }

    [TestMethod]
    public void NormalizeScore_NegativeRaw_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(-1, 100));
    }

    [TestMethod]
    public void NormalizeScore_ZeroMax_Throws()
    {
        Assert.ThrowsExactly<ArgumentOutOfRangeException>(
            () => _calculator.NormalizeScore(50, 0));
    }
}

